const listComputerCheckpointRuns = `-- name: ListComputerCheckpointRuns :many
SELECT checkpoint_id, environment_id, computer_id, run_id, attempt_number, run_wait_id, source_run_lease_id, session_speculative_input_sequence, source_computer_instance_id, writer_generation FROM computer_checkpoint_runs WHERE environment_id=$1
 AND checkpoint_id=$2 ORDER BY run_id
`

type ListComputerCheckpointRunsParams struct {
	EnvironmentID pgtype.UUID `json:"environment_id"`
	CheckpointID  pgtype.UUID `json:"checkpoint_id"`
}

func (q *Queries) ListComputerCheckpointRuns(ctx context.Context, arg ListComputerCheckpointRunsParams) ([]ComputerCheckpointRun, error) {
	rows, err := q.db.Query(ctx, listComputerCheckpointRuns, arg.EnvironmentID, arg.CheckpointID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ComputerCheckpointRun
	for rows.Next() {
		var i ComputerCheckpointRun
		if err := rows.Scan(
			&i.CheckpointID,
			&i.EnvironmentID,
			&i.ComputerID,
			&i.RunID,
			&i.AttemptNumber,
			&i.RunWaitID,
			&i.SourceRunLeaseID,
			&i.SessionSpeculativeInputSequence,
			&i.SourceComputerInstanceID,
			&i.WriterGeneration,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

